Object.assign(SNIP,{});PRESET_NOTES["l22"]={"Ví dụ: Sinh mọi dãy nhị phân độ dài 3": "Cây lời gọi là cây nhị phân đầy đủ: mỗi thu(i) với i < 3 sinh hai con (v = 0 rồi v = 1). 8 lá là 8 dãy, in theo thứ tự từ điển 000, 001, …, 111. Ô x[i] bị ghi đè khi quay lại thử giá trị khác, nên không cần “gỡ”.", "Ví dụ: Sinh tổ hợp chập 2 của 4": "Vị trí i chỉ thử từ x[i − 1] + 1 nên dãy luôn tăng: {1, 2} được sinh, {2, 1} thì không. Cận trên n − k + i chừa đủ chỗ cho các vị trí sau: x[1] không quá 3 vì sau nó còn phải có x[2] > x[1]. Có C(4, 2) = 6 tổ hợp.", "Ví dụ: Sinh hoán vị của 3 số": "Theo dõi mảng dd: một số được bật khi đặt vào x, và tắt ngay khi lời gọi con trả về. Nhờ vậy ở mọi lúc dd mô tả đúng các số đang nằm trên đường từ gốc tới nút hiện tại. 3! = 6 hoán vị.", "Ví dụ: Tập con có tổng bằng S": "Mỗi phần tử có hai nhánh: lấy hoặc bỏ. Khi tổng đã vượt S thì cả nhánh bị bỏ ngay, không đi sâu nữa: cây ít nút hơn 2⁵ − 1 = 31. Kết quả: 3 2 và 1 4.", "Lỗi: quên gỡ đánh dấu khi quay lui": "Chỉ in được 1 2 3. Sau nhánh đầu tiên, dd[1], dd[2], dd[3] đều bật mãi nên mọi nhánh sau không còn số nào để chọn. Chương trình không báo lỗi gì: đây là kiểu lỗi chỉ phát hiện được khi đếm số kết quả (phải là 3! = 6)."};EX_HINTS["l22"]=[["Thử v = 0 trước rồi v = 1 để ra đúng thứ tự từ điển.", "Trước khi đặt 1 vào vị trí i, kiểm tra vị trí i − 1: nếu đã là 1 thì bỏ qua (continue). Nhớ trường hợp i = 0 không có vị trí trước.", "Số dãy là số Fibonacci: n = 12 có 377 dãy."], ["Bắt các số tăng dần: x[i] > x[i − 1]. Vì thế không bao giờ sinh hai lần cùng một tập.", "Đủ k số (i == k) thì in ra; chưa đủ thì gọi thu(i + 1).", "Chấm so từng dòng, bỏ qua dấu cách thừa ở cuối dòng, nhưng thứ tự các dòng phải đúng."], ["Khung giống ví dụ sinh hoán vị, chỉ thay việc in bằng dem++.", "Kiểm tra điều kiện ngay khi đặt v (so với x[i − 1]) thay vì đợi sinh xong cả hoán vị: các nhánh hỏng bị bỏ sớm, chạy nhanh hơn nhiều.", "Nhớ dd[v] = false sau lời gọi đệ quy."]];
/* ===================== BÀI 22 · Quay lui: sinh tổ hợp và hoán vị ===================== */
/* Bài 22 · Quay lui: sinh tổ hợp và hoán vị
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR22=[{label:"Ví dụ: Sinh mọi dãy nhị phân độ dài 3",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 3;\nint x[3];\n\nvoid thu(int i) {\n    if (i == n) {\n        for (int j = 0; j < n; j++) cout << x[j];\n        cout << \"\\n\";\n        return;\n    }\n    for (int v = 0; v <= 1; v++) {\n        x[i] = v;\n        thu(i + 1);\n    }\n}\n\nint main() {\n    thu(0);\n    return 0;\n}",viz:[{type:"cells",of:"x",ptr:["i"]},{type:"calls"}],py:{code:"n = 3\nx = [0] * n\n\ndef thu(i):\n    if i == n:\n        print(\"\".join(map(str, x)))\n        return\n    for v in range(2):\n        x[i] = v\n        thu(i + 1)\n\nthu(0)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 3;\n    static int[] x = new int[3];\n\n    static void Thu(int i)\n    {\n        if (i == n)\n        {\n            Console.WriteLine(string.Join(\"\", x));\n            return;\n        }\n        for (int v = 0; v <= 1; v++)\n        {\n            x[i] = v;\n            Thu(i + 1);\n        }\n    }\n\n    static void Main()\n    {\n        Thu(0);\n    }\n}",note:"Cây lời gọi là cây nhị phân đầy đủ: mỗi Thu(i) với i < 3 sinh hai con (v = 0 rồi v = 1). 8 lá là 8 dãy, in theo thứ tự từ điển 000, 001, …, 111. Ô x[i] bị ghi đè khi quay lại thử giá trị khác, nên không cần “gỡ”."}},{label:"Ví dụ: Sinh tổ hợp chập 2 của 4",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 4, k = 2;\nint x[3];   // dùng x[1..k]; x[0] = 0 để công thức chung cho i = 1\n\nvoid thu(int i) {\n    for (int v = x[i - 1] + 1; v <= n - k + i; v++) {\n        x[i] = v;\n        if (i == k) {\n            for (int j = 1; j <= k; j++) cout << x[j] << \" \";\n            cout << \"\\n\";\n        } else {\n            thu(i + 1);\n        }\n    }\n}\n\nint main() {\n    thu(1);\n    return 0;\n}",viz:[{type:"cells",of:"x",ptr:["i"]},{type:"calls"}],py:{code:"n, k = 4, 2\nx = [0] * (k + 1)   # dùng x[1..k]; x[0] = 0 để công thức chung cho i = 1\n\ndef thu(i):\n    for v in range(x[i - 1] + 1, n - k + i + 1):\n        x[i] = v\n        if i == k:\n            print(*x[1:])\n        else:\n            thu(i + 1)\n\nthu(1)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 4, k = 2;\n    static int[] x = new int[3];   // dùng x[1..k]; x[0] = 0 để công thức chung cho i = 1\n\n    static void Thu(int i)\n    {\n        for (int v = x[i - 1] + 1; v <= n - k + i; v++)\n        {\n            x[i] = v;\n            if (i == k)\n            {\n                for (int j = 1; j <= k; j++) Console.Write(x[j] + \" \");\n                Console.WriteLine();\n            }\n            else\n            {\n                Thu(i + 1);\n            }\n        }\n    }\n\n    static void Main()\n    {\n        Thu(1);\n    }\n}"}},{label:"Ví dụ: Sinh hoán vị của 3 số",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 3;\nint x[3];\nbool dd[4];   // dd[v]: số v đã nằm trong x[0..i-1] chưa\n\nvoid thu(int i) {\n    if (i == n) {\n        for (int j = 0; j < n; j++) cout << x[j] << \" \";\n        cout << \"\\n\";\n        return;\n    }\n    for (int v = 1; v <= n; v++) {\n        if (!dd[v]) {\n            dd[v] = true;\n            x[i] = v;\n            thu(i + 1);\n            dd[v] = false;     // quay lui: trả v lại để nhánh khác dùng\n        }\n    }\n}\n\nint main() {\n    thu(0);\n    return 0;\n}",viz:[{type:"cells",of:"x",ptr:["i"]},{type:"cells",of:"dd",ptr:["v"]},{type:"calls"}],py:{code:"n = 3\nx = [0] * n\ndd = [False] * (n + 1)   # dd[v]: số v đã nằm trong x[0..i-1] chưa\n\ndef thu(i):\n    if i == n:\n        print(*x)\n        return\n    for v in range(1, n + 1):\n        if not dd[v]:\n            dd[v] = True\n            x[i] = v\n            thu(i + 1)\n            dd[v] = False     # quay lui: trả v lại để nhánh khác dùng\n\nthu(0)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 3;\n    static int[] x = new int[3];\n    static bool[] dd = new bool[4];   // dd[v]: số v đã nằm trong x[0..i-1] chưa\n\n    static void Thu(int i)\n    {\n        if (i == n)\n        {\n            Console.WriteLine(string.Join(\" \", x));\n            return;\n        }\n        for (int v = 1; v <= n; v++)\n        {\n            if (!dd[v])\n            {\n                dd[v] = true;\n                x[i] = v;\n                Thu(i + 1);\n                dd[v] = false;     // quay lui: trả v lại để nhánh khác dùng\n            }\n        }\n    }\n\n    static void Main()\n    {\n        Thu(0);\n    }\n}"}},{label:"Ví dụ: Tập con có tổng bằng S",input:"",code:"#include <iostream>\nusing namespace std;\n\nint a[4] = {3, 1, 4, 2};\nint n = 4, S = 5;\nint chon[4], m = 0;    // các số đã chọn: chon[0..m-1]\n\nvoid thu(int i, int tong) {\n    if (tong > S) return;              // cắt nhánh: các số dương, tổng chỉ tăng thêm\n    if (i == n) {\n        if (tong == S) {\n            for (int j = 0; j < m; j++) cout << chon[j] << \" \";\n            cout << \"\\n\";\n        }\n        return;\n    }\n    chon[m++] = a[i];                  // nhánh 1: lấy a[i]\n    thu(i + 1, tong + a[i]);\n    m--;                               // gỡ\n    thu(i + 1, tong);                  // nhánh 2: bỏ a[i]\n}\n\nint main() {\n    thu(0, 0);\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"chon",ptr:["m"]},{type:"calls"}],py:{code:"a = [3, 1, 4, 2]\nn, S = 4, 5\nchon = []    # các số đã chọn\n\ndef thu(i, tong):\n    if tong > S:                  # cắt nhánh: các số dương, tổng chỉ tăng thêm\n        return\n    if i == n:\n        if tong == S:\n            print(*chon)\n        return\n    chon.append(a[i])             # nhánh 1: lấy a[i]\n    thu(i + 1, tong + a[i])\n    chon.pop()                    # gỡ\n    thu(i + 1, tong)              # nhánh 2: bỏ a[i]\n\nthu(0, 0)",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cells",of:"chon"},{type:"calls"}],note:"Mỗi phần tử có hai nhánh: lấy hoặc bỏ. chon là một list dùng như ngăn xếp: append khi lấy, pop khi gỡ. Khi tổng đã vượt S thì cả nhánh bị bỏ ngay. Kết quả: 3 2 và 1 4."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 3, 1, 4, 2 };\n    static int n = 4, S = 5;\n    static int[] chon = new int[4];\n    static int m = 0;    // các số đã chọn: chon[0..m-1]\n\n    static void Thu(int i, int tong)\n    {\n        if (tong > S) return;              // cắt nhánh: các số dương, tổng chỉ tăng thêm\n        if (i == n)\n        {\n            if (tong == S)\n            {\n                for (int j = 0; j < m; j++) Console.Write(chon[j] + \" \");\n                Console.WriteLine();\n            }\n            return;\n        }\n        chon[m++] = a[i];                  // nhánh 1: lấy a[i]\n        Thu(i + 1, tong + a[i]);\n        m--;                               // gỡ\n        Thu(i + 1, tong);                  // nhánh 2: bỏ a[i]\n    }\n\n    static void Main()\n    {\n        Thu(0, 0);\n    }\n}"}},{label:"Lỗi: quên gỡ đánh dấu khi quay lui",input:"",code:"#include <iostream>\nusing namespace std;\n\nint n = 3;\nint x[3];\nbool dd[4];\n\nvoid thu(int i) {\n    if (i == n) {\n        for (int j = 0; j < n; j++) cout << x[j] << \" \";\n        cout << \"\\n\";\n        return;\n    }\n    for (int v = 1; v <= n; v++) {\n        if (!dd[v]) {\n            dd[v] = true;\n            x[i] = v;\n            thu(i + 1);\n            // quên: dd[v] = false;\n        }\n    }\n}\n\nint main() {\n    thu(0);\n    return 0;\n}",viz:[{type:"cells",of:"x",ptr:["i"]},{type:"cells",of:"dd",ptr:["v"]}],py:{code:"n = 3\nx = [0] * n\ndd = [False] * (n + 1)\n\ndef thu(i):\n    if i == n:\n        print(*x)\n        return\n    for v in range(1, n + 1):\n        if not dd[v]:\n            dd[v] = True\n            x[i] = v\n            thu(i + 1)\n            # quên: dd[v] = False\n\nthu(0)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n = 3;\n    static int[] x = new int[3];\n    static bool[] dd = new bool[4];   // dd[v]: số v đã nằm trong x[0..i-1] chưa\n\n    static void Thu(int i)\n    {\n        if (i == n)\n        {\n            Console.WriteLine(string.Join(\" \", x));\n            return;\n        }\n        for (int v = 1; v <= n; v++)\n        {\n            if (!dd[v])\n            {\n                dd[v] = true;\n                x[i] = v;\n                Thu(i + 1);\n                // quên: dd[v] = false;\n            }\n        }\n    }\n\n    static void Main()\n    {\n        Thu(0);\n    }\n}"}}];
